def _tuple_to_dict(tpl):
    """Convert a 5-tuple to a dict with keys major, minor, patch, prerelease, build."""
    if len(tpl) != 5:
        raise TypeError('tuple must have 5 elements')
    return {
        'major': int(tpl[0]),
        'minor': int(tpl[1]),
        'patch': int(tpl[2]),
        'prerelease': str(tpl[3]) if tpl[3] is not None else None,
        'build': str(tpl[4]) if tpl[4] is not None else None,
    }
